// for the repomap perf fixture; it references Func018_21_00
// so the pagerank/refs step in repomap.Build has real edges
// to walk, not an isolated file per symbol.
func Func017_20_00(a, b int) int {
	if a > b {
		return Func018_21_00(a, b) + a
	}
	return Func018_21_00(b, a) - b
}

